READ_LINE_TO_BUFFER:
        ; Read bytes until CR, uppercase a..z, store at LINE_BUF; returns length
        ;@compiled read_line_to_buffer 0724 98
        /*
         * READ_LINE_TO_BUFFER @ 0x0724 in SISNE.SIS (98 bytes).
         *
         * Read a line of console input into LINE_BUF, one byte at a time via
         * READ_BYTE, until a CR (0x0D). Printable bytes (and tab) are stored;
         * lowercase a..z is upper-cased; other control bytes are dropped; the
         * buffer is capped at 0x7F characters. A leading Ctrl-Z (0x1A) on an empty
         * line returns -1 (EOF); an empty CR line is skipped and reading continues.
         * On a complete line a CR terminator is written after the text and the
         * character count is returned.
         */

        extern unsigned char LINE_BUF[128] __addr__(0x0E28);
        extern int           read_byte(void) __addr__(0x00F9);   /* returns byte in AL */

        int read_line_to_buffer(void) __addr__(0x0724)
        {
            register int  len;      /* SI */
            unsigned char ch;       /* [bp-4] */

            len = 0;
            do {
                for (; (ch = read_byte()) != 0x0D; ) {
                    if (ch == 0x1A) break;                  /* Ctrl-Z */
                if (ch <= 0x1F && ch != 9) continue;    /* control char (non-tab) */
                if (len >= 0x7F) continue;              /* buffer full */
                if (ch >= 'a' && ch <= 'z')
                    LINE_BUF[len++] = ch - 0x20;        /* upper-case */
                else
                    LINE_BUF[len++] = ch;
                }
                if (ch == 0x1A && len == 0) return -1;      /* empty + Ctrl-Z -> EOF */
            } while (len == 0);
            LINE_BUF[len] = 0x0D;
            return len;
        }
        ;@endcompiled

