            *(unsigned int far *)(fcb + 0x10) = *(unsigned int far *)(fcb + 0x12) = 0;
            build_dos_datetime(&t, &d);
            *(unsigned int far *)(fcb + 0x14) = t;
            *(unsigned int far *)(fcb + 0x16) = d;
