        test    word [bp+4], 1                                 ;#B7CE: F7 46 04 01 00
        jnz     short READ_FAT12_ODD_NIBBLE                    ;#B7D3: 75 05
        and     ax, 0FFFh                                      ;#B7D5: 25 FF 0F
        jmp     short READ_FAT12_TEST_EOF                      ;#B7D8: EB 04

READ_FAT12_ODD_NIBBLE:
