        mov     cl, 4                                          ;#B7DA: B1 04
        shr     ax, cl                                         ;#B7DC: D3 E8
READ_FAT12_TEST_EOF:
        ; Test result ≡ 0FFFh and expand to 0FFFFh (FAT-12 EOF sentinel)
        cmp     ax, 0FFFh                                      ;#B7DE: 3D FF 0F
        jnz     short READ_FCB_PATH_CHAR_RET                   ;#B7E1: 75 02
        mov     ah, 0FFh                                       ;#B7E3: B4 FF
READ_FCB_PATH_CHAR_RET:
        ; Common return tail of READ_FCB_PATH_CHAR — pop si/di/bp and ret
        pop     si                                             ;#B7E5: 5E
        pop     di                                             ;#B7E6: 5F
        pop     bp                                             ;#B7E7: 5D
        ret                                                    ;#B7E8: C3
        push    bp                                             ;#B7E9: 55
        mov     bp, sp                                         ;#B7EA: 8B EC
        push    di                                             ;#B7EC: 57
        push    si                                             ;#B7ED: 56
        mov     ax, [bp+4]                                     ;#B7EE: 8B 46 04
        cmp     word [1572h], 1000h                            ;#B7F1: 81 3E 72 15 00 10
        jbe     short WRITE_FAT12_ENTRY_CACHED                 ;#B7F7: 76 12
        call    near COMPUTE_FAT_SECTOR_ADDR_NOSHIFT           ;#B7F9: E8 99 00
        mov     ax, [bp+6]                                     ;#B7FC: 8B 46 06
        mov     [es:bx+di], ax                                 ;#B7FF: 26 89 01
        mov     word [1570h], 1                                ;#B802: C7 06 70 15 01 00
        jmp     near WRITE_FCB_FAT_ENTRY_RET                   ;#B808: E9 86 00

WRITE_FAT12_ENTRY_CACHED:
