        push    ax                                             ;#B83C: 50
        inc     si                                             ;#B83D: 46
        push    si                                             ;#B83E: 56
        call    near FAT_WRITE_DIRTY_MCB                       ;#B83F: E8 0E 54
        add     sp, 4                                          ;#B842: 83 C4 04
        les     di, [14E6h]                                    ;#B845: C4 3E E6 14
        mov     dx, [bp+6]                                     ;#B849: 8B 56 06
        and     dh, 0Fh                                        ;#B84C: 80 E6 0F
        mov     word [1570h], 1                                ;#B84F: C7 06 70 15 01 00
        test    word [bp+4], 1                                 ;#B855: F7 46 04 01 00
        jz      short WRITE_FAT12_EVEN_LOW_NIBBLE              ;#B85A: 74 09
        mov     cl, 4                                          ;#B85C: B1 04
        shl     dx, cl                                         ;#B85E: D3 E2
        mov     [es:di], dh                                    ;#B860: 26 88 35
        jmp     short WRITE_FCB_FAT_ENTRY_RET                  ;#B863: EB 2C

WRITE_FAT12_EVEN_LOW_NIBBLE:
        ; Even-cluster: keep high nibble of byte, OR with new low4
