        and     ax, 0F000h                                     ;#B87B: 25 00 F0
        or      ax, dx                                         ;#B87E: 0B C2
        mov     [es:bx+di], ax                                 ;#B880: 26 89 01
        jmp     short WRITE_FCB_FAT_ENTRY_RET                  ;#B883: EB 0C

WRITE_FAT12_INPLACE_WORD_ODD:
        ; In-place word: shift value left 4, mask low 12 bits, OR (odd cluster)
        mov     cl, 4                                          ;#B885: B1 04
        shl     dx, cl                                         ;#B887: D3 E2
        and     ax, 0Fh                                        ;#B889: 25 0F 00
        or      ax, dx                                         ;#B88C: 0B C2
        mov     [es:bx+di], ax                                 ;#B88E: 26 89 01
WRITE_FCB_FAT_ENTRY_RET:
        ; Common return tail of WRITE_FCB_FAT_ENTRY — pop si/di/bp and ret
        pop     si                                             ;#B891: 5E
        pop     di                                             ;#B892: 5F
        pop     bp                                             ;#B893: 5D
        ret                                                    ;#B894: C3

COMPUTE_FAT_SECTOR_ADDR_NOSHIFT:
        ; AX already shifted — fall directly into FAT_SECTOR_ADDR's common tail
        mov     si, ax                                         ;#B895: 8B F0
        jmp     short FAT_SECTOR_ADDR_RANGE_LO                 ;#B897: EB 04

COMPUTE_FAT_SECTOR_ADDR:
