        les     di, [14E6h]                                    ;#B8C8: C4 3E E6 14
        mov     bx, si                                         ;#B8CC: 8B DE
        sub     bx, [14EAh]                                    ;#B8CE: 2B 1E EA 14
        ret                                                    ;#B8D2: C3

MEM_COPY_FAR:
