        pop     ds                                             ;#B8E7: 1F
        pop     bp                                             ;#B8E8: 5D
        ret                                                    ;#B8E9: C3

DOS_FN_0E_SELECT_DISK:
        ; INT 21h AH=0Eh handler (select disk)
        ; Standard MS-DOS AH=0Eh "Select Default Drive". Sets the current drive
        ; to DL (0=A:, 1=B:, ...). Returns the total drive count in AL.
        ;
        ; Body:
        ; - RESOLVE_DRIVE_MAPPING(DL): walks the DPB chain for substitutions
        ; and returns the physical drive. CF=set if drive is invalid.
        ; - If valid and not redir-flagged (bit 13 of returned AX), store DL
        ; at [2E4h] (current-drive cell). Otherwise fall through without
        ; updating — the existing default stays.
        ; - SET_DEFAULT_DRIVE_TAIL writes the drive count from [1CCh] into
        ; caller's AL (via `les di, [bp+2]; mov [es:di], al`).
        ;
        ; @return  AL = number of drives configured.
        mov     bp, sp                                         ;#B8EA: 8B EC
        call    near RESOLVE_DRIVE_MAPPING                     ;#B8EC: E8 60 FE
        jb      short SET_DEFAULT_DRIVE_TAIL                   ;#B8EF: 72 09
        test    ax, 2000h                                      ;#B8F1: A9 00 20
        jnz     short SET_DEFAULT_DRIVE_TAIL                   ;#B8F4: 75 04
        mov     [2E4h], dl                                     ;#B8F6: 88 16 E4 02
SET_DEFAULT_DRIVE_TAIL:
        ; Store drive count [1CCh] at [es:di] (default-drive query result)
        les     di, [bp+2]                                     ;#B8FA: C4 7E 02
        mov     al, [1CCh]                                     ;#B8FD: A0 CC 01
        mov     [es:di], al                                    ;#B900: 26 88 05
        ret                                                    ;#B903: C3

DOS_FN_19_GET_CURRENT_DRIVE:
        ; INT 21h AH=19h handler (get current drive)
        ; Standard MS-DOS AH=19h "Get Current Drive". Returns the current
        ; default drive in AL (0=A:, 1=B:, ...).
        ;
        ; Body: 5 instructions — read [2E4h] (the SDA current-drive cell), write
        ; it to caller's AL slot in saved-regs at `[ES:DI]`, ret.
        ;
        ; @return  AL = current drive index.
        mov     bp, sp                                         ;#B904: 8B EC
        mov     al, [2E4h]                                     ;#B906: A0 E4 02
        les     di, [bp+2]                                     ;#B909: C4 7E 02
        mov     [es:di], al                                    ;#B90C: 26 88 05
        ret                                                    ;#B90F: C3

