        les     bx, [bp+2]                                     ;#C8F1: C4 5E 02
        mov     bx, [es:bx+14h]                                ;#C8F4: 26 8B 5F 14
        sub     ax, ax                                         ;#C8F8: 2B C0
        jmp     short INT22_EXIT_DISPATCH                      ;#C8FA: EB 06

