        ; Match BIOS INT 16h ext scan codes (7200h..5D84h) and emit control byte in AL
        push    bx                                             ;#DC8E: 53
        push    ds                                             ;#DC8F: 1E
        mov     bx, 0FA1h                                      ;#DC90: BB A1 0F
        mov     ds, bx                                         ;#DC93: 8E DB
